function navIdForRoute(page){
  if(page==='domain') return 'domains';
  if(page==='lesson') return 'lessons';
  return page || 'home';
}
const publicBasePath=(import.meta.env.BASE_URL||'/').replace(/\/$/,'');
const publicBaseHref=publicBasePath&&publicBasePath!=='.'?publicBasePath:'';
const siteOrigin='https://carlashub.github.io';
const siteBaseUrl=siteOrigin+'/gh600-agentic-ai-study-site';
function routePath(page,id){
  if(!page||page==='home') return '/';
  if(page==='domain') return '/domain/'+encodeURIComponent(id||'domain-1')+'/';
  if(page==='lesson') return '/lesson/'+encodeURIComponent(id||lessons[0].id)+'/';
  if(page==='library') return id?'/library/'+encodeURIComponent(id)+'/':'/library/';
  if(page==='labs') return id?'/labs/'+encodeURIComponent(id)+'/':'/labs/';
  if(page==='quiz') return id?'/quiz/'+encodeURIComponent(id)+'/':'/quiz/';
  if(page==='mock') return id?'/mock/'+encodeURIComponent(id)+'/':'/mock/';
  if(page==='glossary') return id?'/glossary/'+encodeURIComponent(id)+'/':'/glossary/';
  if(page==='walkthroughs') return id?'/walkthroughs/'+encodeURIComponent(id)+'/':'/walkthroughs/';
  return '/'+encodeURIComponent(page)+'/';
}
function routeHref(page,id){return publicBaseHref+routePath(page,id)}
function assetHref(path){return publicBaseHref+'/'+path.replace(/^\/+/,'')}
function parseRoutePath(pathname){
  let path=pathname||'/';
  if(publicBaseHref&&path.startsWith(publicBaseHref)) path=path.slice(publicBaseHref.length)||'/';
  const parts=path.replace(/^\/+|\/+$/g,'').split('/').filter(Boolean).map(decodeURIComponent);
  if(parts.length===0) return {page:'home'};
  const [first,id]=parts;
  const aliases={ 'mock-exams':'mock', exams:'mock', 'study-plans':'study-plan', lab:'labs' };
  let page=aliases[first]||first;
  if(page==='lessons'&&id) page='lesson';
  if(page==='domains'&&id) page='domain';
  if(page==='quizzes') page='quiz';
  if(['blueprint','domains','lessons','walkthroughs','library','labs','quiz','mock','flashcards','glossary','readiness','accuracy','study-plan','cram','domain','lesson'].includes(page)) return {page,id};
  return {page:'home'};
}
function routeSeo(route){
  const page=route?.page||'home';
  const id=route?.id;
  const fallback={title:'GH-600 Agentic AI Study Platform',description:'Complete GH-600 Developing in Agentic AI Systems study platform with lessons, labs, quizzes, mock exams, flashcards, glossary, and source coverage.',url:siteBaseUrl+routePath('home')};
  if(page==='lesson'){const l=byId(lessons,id); if(l) return {title:l.title+' | GH-600 Lesson',description:l.whyExam,url:siteBaseUrl+routePath(page,id),type:'lesson',item:l};}
  if(page==='domain'){const d=blueprint.domains.find(x=>x.id===id); if(d) return {title:d.title+' | GH-600 Module',description:d.whatExamTests,url:siteBaseUrl+routePath(page,id),type:'domain',item:d};}
  if(page==='library'){const t=id&&templateLibrary.templates.find(x=>x.id===id); if(t) return {title:t.title+' | Agent Documentation Template',description:t.goal,url:siteBaseUrl+routePath(page,id),type:'template',item:t}; return {title:templateLibrary.title,description:templateLibrary.summary,url:siteBaseUrl+routePath(page),type:'library'};}
  if(page==='labs'){const lab=id&&byId(labs,id); if(lab) return {title:lab.title+' | GH-600 Lab',description:lab.objective,url:siteBaseUrl+routePath(page,id),type:'lab',item:lab}; return {title:'GH-600 Practical Labs',description:'Hands-on GH-600 labs for GitHub artifacts, validation evidence, recovery habits, and agentic SDLC workflows.',url:siteBaseUrl+routePath(page),type:'labs'};}
  if(page==='glossary'){const term=id&&byId(glossary,id); if(term) return {title:term.term+' | GH-600 Glossary',description:term.definition,url:siteBaseUrl+routePath(page,id),type:'glossary',item:term}; return {title:'GH-600 Glossary',description:'Search GitHub, AI-agent, governance, MCP, and SDLC terms for the GH-600 exam.',url:siteBaseUrl+routePath(page),type:'glossary'};}
  if(page==='walkthroughs'){const item=id&&byId(uiWalkthroughs,id); if(item) return {title:item.title+' | GH-600 Walkthrough',description:item.examTrap,url:siteBaseUrl+routePath(page,id),type:'walkthrough',item};}
  const labels={blueprint:['GH-600 Exam Blueprint','Official GH-600 skill coverage mapped to lessons, quiz questions, labs, flashcards, and sources.'],domains:['GH-600 Course Modules','Six GH-600 study modules following the official exam domains.'],lessons:['All GH-600 Lessons','Full lesson library for GH-600 Developing in Agentic AI Systems.'],walkthroughs:['GitHub Control-Plane Walkthroughs','Accessible study walkthroughs for GH-600 GitHub workflows and control points.'],quiz:['GH-600 Quiz Engine','Immediate feedback practice for GH-600 domains, skills, and scenario judgement.'],mock:['GH-600 Exam Simulator','Timed GH-600 scenario exam simulator aligned to domain weights.'],flashcards:['GH-600 Flashcards','Search, flip, and review GH-600 flashcards for exam recall.'],readiness:['GH-600 Readiness Dashboard','Study readiness evidence based on lessons, mock scores, quiz practice, and labs.'],accuracy:['GH-600 Accuracy Dashboard','Source monitoring and content validation for the GH-600 study platform.'],'study-plan':['GH-600 Study Plans','Choose a GH-600 study schedule based on your exam timeline.'],cram:['GH-600 Cram Guide','Final GH-600 review for high-yield agentic AI, MCP, GitHub, and governance topics.']};
  if(labels[page]) return {title:labels[page][0],description:labels[page][1],url:siteBaseUrl+routePath(page),type:page};
  return fallback;
}
function structuredDataForRoute(route,seo){
  const base={"@context":"https://schema.org","@type":"Course",name:"GH-600 Developing in Agentic AI Systems Study Platform",description:routeSeo({page:'home'}).description,url:siteBaseUrl+'/',provider:{"@type":"Person",name:"Carla Goncalves",url:"https://carlashub.com"}};
  if(!seo?.type||seo.type==='home') return base;
  if(seo.type==='lesson') return {"@context":"https://schema.org","@type":"LearningResource",name:seo.item.title,description:seo.description,learningResourceType:"Lesson",educationalLevel:"Professional certification preparation",isPartOf:base,url:seo.url};
  if(seo.type==='lab') return {"@context":"https://schema.org","@type":"LearningResource",name:seo.item.title,description:seo.description,learningResourceType:"Hands-on lab",educationalLevel:"Professional certification preparation",isPartOf:base,url:seo.url};
  if(seo.type==='template') return {"@context":"https://schema.org","@type":"CreativeWork",name:seo.item.title,description:seo.description,learningResourceType:"Documentation template",isPartOf:base,url:seo.url};
  if(seo.type==='walkthrough') return {"@context":"https://schema.org","@type":"LearningResource",name:seo.item.title,description:seo.description,learningResourceType:"Walkthrough",educationalLevel:"Professional certification preparation",isPartOf:base,url:seo.url};
  if(seo.type==='quiz') return {"@context":"https://schema.org","@type":"Quiz",name:seo.title,description:seo.description,educationalLevel:"Professional certification preparation",isPartOf:base,url:seo.url};
  return {"@context":"https://schema.org","@type":"WebPage",name:seo.title,description:seo.description,isPartOf:base,url:seo.url};
}
function setMeta(selector,attr,value){
  let node=document.head.querySelector(selector);
  if(!node){node=document.createElement(selector.startsWith('meta')?'meta':'link'); const match=selector.match(/\[(name|property|rel)="([^"]+)"\]/); if(match) node.setAttribute(match[1],match[2]); document.head.appendChild(node);}
  node.setAttribute(attr,value);
}
function applyRouteSeo(route){
  const seo=routeSeo(route);
  document.title=seo.title;
  setMeta('meta[name="description"]','content',seo.description);
  if(route?.page&&route.page!=='home') setMeta('link[rel="canonical"]','href',seo.url);
  setMeta('meta[property="og:title"]','content',seo.title);
  setMeta('meta[property="og:description"]','content',seo.description);
  if(route?.page&&route.page!=='home') setMeta('meta[property="og:url"]','content',seo.url);
  setMeta('meta[name="twitter:title"]','content',seo.title);
  setMeta('meta[name="twitter:description"]','content',seo.description);
  let script=document.getElementById('route-structured-data');
  if(!script){script=document.createElement('script'); script.type='application/ld+json'; script.id='route-structured-data'; document.head.appendChild(script);}
  script.textContent=JSON.stringify(structuredDataForRoute(route,seo));
}
function useHashRoute(){
  const parse=()=>{
    if(!location.hash||location.hash==='#') return parseRoutePath(location.pathname);
    const raw=location.hash.replace(/^#/,'')||'home';
    const path=raw.split('?')[0];
    const [initialPage,id]=path.split('/');
    const aliases={ 'mock-exams':'mock', exams:'mock', 'study-plans':'study-plan' };
    let page=aliases[initialPage]||initialPage;
    if(page==='lessons'&&id) page='lesson';
    if(page==='domains'&&id) page='domain';
    if(page==='quizzes') page='quiz';
    if(page==='lab') page='labs';
    return {page,id};
  };
  const [route,setRoute]=useState(parse);
  useEffect(()=>{const on=()=>setRoute(parse()); addEventListener('hashchange',on); return()=>removeEventListener('hashchange',on);},[]);
  return route;
}
function useProgress(){
  const [progress,setProgress]=useState(()=>JSON.parse(localStorage.getItem('gh600-progress-v2')||'{"lessons":{},"flashcards":{},"quizScores":{},"mockScores":{}}'));
  const save=(next)=>{setProgress(next); localStorage.setItem('gh600-progress-v2',JSON.stringify(next));};
  return [progress,save];
}
function pct(done,total){return total?Math.round((done/total)*100):0}
function byId(list,id){return list.find(x=>x.id===id)}
function sourceNames(ids){return ids.map(id=>byId(sources,id)).filter(Boolean)}
function countLabel(count,label){return count+' '+label+(count===1?'':'s')}
function getLessonPractice(lesson){
 const lessonQuizzes=(lesson.relatedQuiz?.length?lesson.relatedQuiz.map(id=>byId(quizzes,id)).filter(Boolean):quizzes.filter(q=>q.lessonId===lesson.id));
 const lessonLabs=(lesson.relatedLabs?.length?lesson.relatedLabs.map(id=>byId(labs,id)).filter(Boolean):labs.filter(lab=>(lab.skillIds||[]).includes(lesson.skillId)));
 const lessonMocks=mockExams.filter(exam=>(exam.questionIds||[]).some(id=>lessonQuizzes.some(q=>q.id===id)));
 return { lessonQuizzes, lessonLabs, lessonMocks };
}
function getFollowSteps(lesson){
 const lab=(lesson.relatedLabs||[]).map(id=>byId(labs,id)).find(Boolean)||labs.find(item=>(item.skillIds||[]).includes(lesson.skillId));
 return [
  'Name the real GitHub object involved: issue, branch, pull request, workflow run, environment, MCP server, instruction file, or review.',
  'Write the safe boundary first: what the agent may touch, what it must not touch, and what evidence it must produce.',
  lesson.githubDetail,
  lab ? 'Do the related lab and keep the artifact reviewable: '+lab.title+'.' : 'Create a tiny practice artifact: a task contract, checklist, decision table, or review note for this skill.',
  'Answer the related quiz questions, then explain why each wrong answer would create risk or reduce accountability.'
 ];
}
function templateForPath(filePath){return templateLibrary.templates.find(t=>t.filePath===filePath||(t.aliases||[]).includes(filePath))}
function NotFound({type,id,backHref}){return <section><PageTitle eyebrow="Missing content" title={type+' not found'} text={'I could not find '+id+'. Use the button below to return to the related library.'}/><a className="button primary" href={backHref}>Open library</a></section>}
function Layout({children,progress,route}){
 const done=Object.values(progress.lessons||{}).filter(Boolean).length;
 const activeNav=navIdForRoute(route?.page);
 return <><a className="skip-link" href="#main">Skip to content</a><header className="topbar"><a className="brand" href={routeHref('home')}><img className="brand-logo" src={assetHref('cat-microsoft.png')} alt="CarlaHub cat logo in Microsoft colors"/><strong>GH-600 Study Platform</strong></a><nav aria-label="Primary navigation">{navItems.map(([id,label,Icon])=>{const active=activeNav===id; return <a key={id} href={routeHref(id)} aria-current={active?'page':undefined} className={active?'active':''}><Icon size={16} aria-hidden="true" />{label}</a>})}</nav></header><main id="main" className={'shell page-'+activeNav}>{children}</main><footer><div className="footer-inner"><div><strong>CarlaHub</strong><p>Unofficial GH-600 study resource. Always verify current exam objectives with Microsoft Learn before sitting the exam.</p><p>{done}/{lessons.length} lessons marked studied ({pct(done,lessons.length)}%).</p></div><nav className="footer-links" aria-label="CarlaHub links">{socialLinks.map(([label,url,Icon])=><a key={label} href={url} target="_blank" rel="noreferrer"><Icon size={16} aria-hidden="true"/>{label}</a>)}</nav></div></footer></>;
}
function Stat({label,value,icon:Icon}){return <div className="stat"><Icon aria-hidden="true"/><strong>{value}</strong><span>{label}</span></div>}
function ProgressBar({value,label}){return <div className="progress"><div><span>{label}</span><strong>{value}%</strong></div><meter min="0" max="100" value={value}>{value}%</meter></div>}
function SourcePanel({ids}){const list=sourceNames(ids); return <aside className="source-panel"><h3>Related sources</h3>{list.map(s=><a key={s.id} href={s.url} target="_blank" rel="noreferrer"><strong>{s.title}</strong><span>{s.publisher}{s.accessed?' · reviewed '+s.accessed:''}</span></a>)}</aside>}
function Breadcrumbs({items,current}){return <nav className="breadcrumbs" aria-label="Breadcrumb"><ol><li><a href="#home">Home</a></li>{items.map(item=><li key={item.href}><a href={item.href}>{item.label}</a></li>)}<li aria-current="page">{current}</li></ol></nav>}
function LessonTracker({lesson,practice}){const lessonIndex=lessons.findIndex(item=>item.id===lesson.id)+1; const domainLessons=lessons.filter(item=>item.domainId===lesson.domainId); const domainIndex=domainLessons.findIndex(item=>item.id===lesson.id)+1; return <aside className="lesson-tracker" aria-label="Lesson position"><h2>Your position</h2><p className="tracker-label">Course lesson</p><ProgressBar label={lessonIndex+' of '+lessons.length} value={pct(lessonIndex,lessons.length)}/><p className="tracker-label">This domain</p><ProgressBar label={domainIndex+' of '+domainLessons.length} value={pct(domainIndex,domainLessons.length)}/><dl className="lesson-meta"><div><dt>Domain</dt><dd>{lesson.domain}</dd></div><div><dt>Difficulty</dt><dd>{lesson.difficulty}</dd></div><div><dt>Practice</dt><dd>{countLabel(practice.lessonQuizzes.length,'question')} · {countLabel(practice.lessonLabs.length,'lab')} · {countLabel(practice.lessonMocks.length,'mock exam')}</dd></div></dl></aside>}
function Home({progress}){
 const studied=Object.values(progress.lessons||{}).filter(Boolean).length;
 const next=lessons.find(l=>!progress.lessons?.[l.id])||lessons[0];
 const domainStats=blueprint.domains.map(d=>{const dl=lessons.filter(l=>l.domainId===d.id); return {...d, percent:pct(dl.filter(l=>progress.lessons?.[l.id]).length,dl.length)}});
 return <section><div className="hero"><div><p className="eyebrow">Microsoft/GitHub certification prep</p><h1>GH-600: Developing in Agentic AI Systems</h1><p>A source-grounded course for learning agentic SDLC workflows, Copilot coding agent, MCP, GitHub controls, evaluation, multi-agent coordination, guardrails, and accountability.</p><section className="guide-card start-guide"><h2>Start here</h2><p>If this is your first visit, begin with the six modules. They are the course path. Each module contains lessons, practice questions, labs, and review work.</p><ol className="steps"><li>Open <strong>Modules</strong> and start with Module 1.</li><li>Read lessons in order and mark them studied as you go.</li><li>Use the embedded questions to check each concept.</li><li>Complete one lab after the module so the idea becomes practical.</li><li>Use quizzes and mock exams after you have studied, not before.</li></ol></section><div className="actions"><a className="button primary" href="#domains">Start with modules</a><a className="button" href={'#lesson/'+next.id}>Resume next lesson</a><a className="button" href="#study-plan">Choose a study plan</a></div></div><div className="panel"><h2>Your next step</h2><p>{next.title}</p><p className="muted">{next.domain}</p><ProgressBar label="Total progress" value={pct(studied,lessons.length)} /></div></div><div className="stats"><Stat icon={BookOpen} label="Course modules" value={blueprint.domains.length}/><Stat icon={FileText} label="Lessons" value={lessons.length}/><Stat icon={FlaskConical} label="Labs" value={labs.length}/><Stat icon={ClipboardList} label="Quiz questions" value={quizzes.length}/><Stat icon={Timer} label="Exam simulator forms" value={[...new Set(examSimulatorQuestions.map(q=>q.form))].length}/><Stat icon={Brain} label="Flashcards" value={flashcards.length}/><Stat icon={CheckCircle2} label="Official skills mapped" value={coverageMatrix.length}/></div><section className="grid two"><div className="panel"><h2>How the site works</h2><ol className="steps"><li><strong>Modules</strong> are the main course sequence.</li><li><strong>Lessons</strong> explain one exam skill in plain language.</li><li><strong>Labs</strong> turn the lesson into GitHub practice.</li><li><strong>Quiz</strong> checks weak areas after study.</li><li><strong>Mock exam</strong> is for readiness practice.</li><li><strong>Cram guide</strong> is final review only.</li></ol></div><div className="panel"><h2>Module readiness</h2>{domainStats.map(d=><ProgressBar key={d.id} label={d.title+' '+d.weight} value={d.percent}/>)}</div></section></section>

}
function Blueprint(){return <section><PageTitle eyebrow="Exam blueprint" title="Official skill coverage map" text="Every official GH-600 skill is mapped to lessons, quiz questions, labs, flashcards, and sources."/><div className="domain-strip">{blueprint.domains.map(d=><a href={'#domain/'+d.id} className="domain-card" key={d.id}><span>{d.weight}</span><strong>{d.title}</strong><p>{d.whatExamTests}</p></a>)}</div><div className="table-wrap"><table><thead><tr><th>Skill</th><th>Domain</th><th>Lesson</th><th>Quiz</th><th>Lab</th><th>Status</th></tr></thead><tbody>{coverageMatrix.map(r=><tr key={r.id}><td>{r.skill}</td><td>{r.domain}</td><td>{r.lessonIds.map(id=><a key={id} href={'#lesson/'+id}>{id}</a>)}</td><td>{r.quizQuestionIds.length}</td><td>{r.labIds.join(', ')}</td><td><span className="badge good">{r.coverageStatus}</span></td></tr>)}</tbody></table></div></section>}
function Domains({progress}){return <section><PageTitle eyebrow="Modules" title="Start with the six course modules" text="These modules follow the official GH-600 exam domains. Open Module 1 first, study its lessons, then do the related labs and quiz practice before moving to the next module."/><section className="guide-card start-guide"><h2>Where to begin</h2><ol className="steps"><li>Start with Module 1: Prepare agent architecture and SDLC processes.</li><li>Open each lesson in that module from top to bottom.</li><li>After each lesson, use the embedded practice questions to check understanding.</li><li>When the module feels familiar, complete one related lab and then try the quiz.</li><li>Use the cram guide only at the end, after the modules are no longer new.</li></ol><div className="actions"><a className="button primary" href="#domain/domain-1">Open Module 1</a><a className="button" href="#study-plan">Choose a study plan</a></div></section><div className="domain-grid">{blueprint.domains.map(d=><DomainCard key={d.id} domain={d} progress={progress}/>)}</div></section>}
function DomainCard({domain,progress}){const dl=lessons.filter(l=>l.domainId===domain.id); const done=dl.filter(l=>progress.lessons?.[l.id]).length; return <article className="domain-card"><span>{domain.weight}</span><h2>{domain.title}</h2><p>{domain.whatExamTests}</p><ProgressBar label="Lessons studied" value={pct(done,dl.length)}/><a className="button" href={'#domain/'+domain.id}>Open domain</a></article>}
function DomainPage({id,progress,setProgress}){const d=blueprint.domains.find(x=>x.id===id)||blueprint.domains[0]; const dl=lessons.filter(l=>l.domainId===d.id); return <section><PageTitle eyebrow={d.weight} title={d.title} text={d.whatExamTests}/><div className="grid two"><div className="panel"><h2>What the exam is really testing</h2><p>{d.whatExamTests}</p><h3>Recommended study order</h3><ol>{d.groups.map(g=><li key={g.id}>{g.title}</li>)}</ol></div><div className="panel"><h2>Key exam traps</h2><ul><li>Giving agents broad tools without a task-specific need.</li><li>Accepting claims without logs, checks, artifacts, or review evidence.</li><li>Skipping human approval for sensitive, irreversible, production, or compliance-relevant work.</li><li>Using many agents without isolation and handoff contracts.</li></ul></div></div>{d.groups.map(g=><section key={g.id} className="panel"><h2>{g.title}</h2><div className="lesson-list">{dl.filter(l=>l.group===g.title).map(l=><LessonRow key={l.id} lesson={l} progress={progress} setProgress={setProgress}/>)}</div></section>)}<section className="panel"><h2>Additional practical knowledge</h2><div className="lesson-list">{dl.filter(l=>l.extended).map(l=><LessonRow key={l.id} lesson={l} progress={progress} setProgress={setProgress}/>)}</div></section></section>}
