function Lessons({progress,setProgress}){const [q,setQ]=useState(''); const filtered=lessons.filter(l=>(l.title+l.domain+l.group).toLowerCase().includes(q.toLowerCase())); return <section><PageTitle eyebrow="Lessons" title="All lessons" text="This is the full lesson library. If you are new, do not start here randomly: open Modules first, begin with Module 1, and use this page only when you want to search for a specific topic."/><label className="search"><Search aria-hidden="true"/><span className="sr-only">Search lessons</span><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search lessons, domains, skills"/></label><div className="lesson-list">{filtered.map(l=><LessonRow key={l.id} lesson={l} progress={progress} setProgress={setProgress}/>)}</div></section>}
function ArtifactEntry({item}){const template=templateForPath(item.path); return <div><dt>{template?<a href={'#library/'+template.id}>{item.path}</a>:item.path}</dt><dd>{item.purpose}{template&&<span className="artifact-library-link">Template: <a href={'#library/'+template.id}>{template.title}</a></span>}</dd></div>}
function LessonActionSections({l}){const artifacts=l.filesToCreate||[]; return <><section className="action-section"><p className="eyebrow">Do this in GitHub</p><h2>What you actually do</h2>{l.actionOverview&&<p>{l.actionOverview}</p>}<ol className="action-steps">{(l.actionSteps||[]).map((step,index)=><li key={step}><span>{index+1}</span><p>{step}</p></li>)}</ol></section>{artifacts.length>0&&<section className="action-section"><p className="eyebrow">Names to recognise</p><h2>Files, settings, and artifacts to create</h2><p className="muted">These are the concrete things a developer or platform team would usually create, review, or configure so the agent work is traceable and governed.</p><dl className="artifact-list">{artifacts.map(item=><ArtifactEntry key={item.path} item={item}/>)}</dl><p><a className="button small" href="#library">Open template library</a></p></section>}{l.agentRequestTemplate&&<section className="action-section"><p className="eyebrow">Copyable direction</p><h2>Agent request you can use</h2><p className="muted">Use this style of request when assigning work to an agent. It forces scope, evidence, validation, and approval points before the agent starts changing files.</p><pre className="prompt-box"><code>{l.agentRequestTemplate}</code></pre></section>}{l.enterpriseChecklist?.length>0&&<section className="action-section"><p className="eyebrow">Enterprise standard</p><h2>How a professional team would check this</h2><ul className="checklist">{l.enterpriseChecklist.map(item=><li key={item}>{item}</li>)}</ul></section>}{l.whatNotToDo?.length>0&&<section className="action-section avoid-section"><p className="eyebrow">Avoid this</p><h2>What not to do</h2><ul>{l.whatNotToDo.map(item=><li key={item}>{item}</li>)}</ul></section>}{l.examActionDrill?.length>0&&<section className="action-section"><p className="eyebrow">Exam drill</p><h2>Exam strategy</h2><ol>{l.examActionDrill.map(item=><li key={item}>{item}</li>)}</ol></section>}{l.keyTerms?.length>0&&<section className="key-terms" aria-label="Key terms in this lesson"><h2>Key terms and short names</h2><div>{l.keyTerms.map(term=><a key={term} href={'#glossary?search='+encodeURIComponent(term)}>{term}</a>)}</div></section>}</>}
function LessonTeachingTable({table}){if(!table?.rows?.length)return null; const columns=table.columns||[]; return <section className="table-wrap lesson-teaching-table"><h2>{table.title||'Decision table'}</h2>{table.intro&&<p>{table.intro}</p>}<table><thead><tr>{columns.map((column,index)=><th key={column||index}>{column}</th>)}</tr></thead><tbody>{table.rows.map((row,rowIndex)=><tr key={row.join('|')||rowIndex}>{row.map((cell,index)=><td key={columns[index]||index}>{cell}</td>)}</tr>)}</tbody></table></section>}
function LessonDeepeningSections({l}){const worked=l.workedExamQuestion; const table=l.teachingTable; const ui=l.uiConfigExample; return <>{worked&&<section className="action-section worked-question"><p className="eyebrow">Worked example</p><h2>{worked.title||'Worked exam-style question'}</h2>{worked.scenario&&<p>{worked.scenario}</p>}<h3>{worked.question}</h3><ol className="worked-options">{(worked.options||[]).map((option,index)=><li key={option} className={index===worked.correctIndex?'correct-option':''}><span>{String.fromCharCode(65+index)}</span><p>{option}</p></li>)}</ol>{worked.strongAnswer&&<p><strong>Strong answer:</strong> {worked.strongAnswer}</p>}{worked.whyWrong?.length>0&&<div className="worked-rationales"><h3>Why the other answers fail</h3><ul>{worked.whyWrong.map(item=><li key={item.optionIndex}><strong>{String.fromCharCode(65+item.optionIndex)}:</strong> {item.rationale}</li>)}</ul></div>}{worked.examTip&&<p className="muted">{worked.examTip}</p>}</section>}<LessonTeachingTable table={table}/>{ui&&<section className="action-section config-example"><p className="eyebrow">Configuration example</p><h2>{ui.title}</h2>{ui.intro&&<p>{ui.intro}</p>}<ol>{(ui.steps||[]).map(step=><li key={step}>{step}</li>)}</ol>{ui.expectedEvidence&&<p><strong>{ui.expectedEvidence}</strong></p>}{ui.sourceNotes?.length>0&&<ul className="muted">{ui.sourceNotes.map(note=><li key={note}>{note}</li>)}</ul>}</section>}</>}
function TopicSpecificExplanation({item}){if(!item?.paragraphs?.length)return null; return <section className="action-section topic-specific"><p className="eyebrow">Topic focus</p><h2>{item.title||'What is different about this topic'}</h2>{item.category&&<h3>{item.category}</h3>}{item.paragraphs.map(paragraph=><p key={paragraph}>{paragraph}</p>)}{item.distinctions?.length>0&&<ul>{item.distinctions.map(point=><li key={point}>{point}</li>)}</ul>}{item.examConnection&&<p className="muted">{item.examConnection}</p>}</section>}
function PracticalLabTask({lab,task}){const content=task||lab; if(!content)return null; const title=content.title||lab?.title; const objective=content.objective||lab?.objective; const steps=content.steps||lab?.steps||[]; return <section className="action-section practical-lab-task"><p className="eyebrow">Hands-on task</p><h2>Practical lab task</h2><p><strong>{title}</strong></p><p>{objective}</p>{steps.length>0&&<ol>{steps.slice(0,5).map(step=><li key={step}>{step}</li>)}</ol>}{content.deliverable&&<p><strong>Deliverable:</strong> {content.deliverable}</p>}{lab&&<p><a className="button small" href={'#labs/'+lab.id}>Open full lab</a></p>}</section>}
function Lesson({id,progress,setProgress}){const [inlineAnswers,setInlineAnswers]=useState({}); const l=byId(lessons,id); if(!l) return <NotFound type="Lesson" id={id||'unknown'} backHref="#lessons"/>; const practice=getLessonPractice(l); const {lessonQuizzes,lessonLabs,lessonMocks}=practice; const relatedQ=lessonQuizzes.slice(0,5); const embeddedQ=lessonQuizzes.slice(0,3); const relatedLab=lessonLabs[0]; const sc=l.scenario||scenarios.find(s=>s.lessonId===l.id); const plainLanguage=l.plainLanguage?.length?l.plainLanguage:[`This lesson is about turning ${l.officialSkill} into something a developer can actually do inside GitHub. Think of the agent as a capable teammate: useful when the task is clear, risky when the boundary is vague, and trustworthy only when its work leaves evidence.`,'The exam wants you to choose the answer that makes the work scoped, repeatable, reviewable, and safe. If an option depends on the agent probably knowing what it is doing, treat that as a warning sign.']; const index=lessons.findIndex(item=>item.id===l.id); const prev=lessons[index-1]; const next=lessons[index+1]; return <section><Breadcrumbs items={[{label:'Lessons',href:'#lessons'},{label:l.domain,href:'#domain/'+l.domainId}]} current={l.title}/><PageTitle eyebrow={l.domain} title={l.title} text={l.whyExam}/><div className="lesson-page"><article className="lesson-content lesson"><div className="toolbar lesson-actions"><button className="button small" onClick={()=>setProgress({...progress,lessons:{...progress.lessons,[l.id]:!progress.lessons?.[l.id]}})}>{progress.lessons?.[l.id]?'Mark not studied':'Mark studied'}</button>{prev&&<a className="button small" href={'#lesson/'+prev.id}>Previous lesson</a>}{next&&<a className="button small" href={'#lesson/'+next.id}>Next lesson</a>}</div><section className="guide-card"><p className="eyebrow">Start here</p><h2>Plain-language idea</h2>{plainLanguage.map((p,i)=><p key={i}>{p}</p>)}</section><dl className="lesson-summary-list" aria-label="Lesson practice summary"><div><dt>Quiz questions</dt><dd>{lessonQuizzes.length}</dd></div><div><dt>Hands-on labs</dt><dd>{lessonLabs.length}</dd></div><div><dt>Mock exams</dt><dd>{lessonMocks.length}</dd></div></dl><h2>Official skill</h2><p>{l.officialSkill}</p><h2>Core explanation</h2>{l.core.map((p,i)=><p key={i}>{p}</p>)}<TopicSpecificExplanation item={l.topicSpecificExplanation}/><LessonActionSections l={l}/><h2>Quick workflow recap</h2><ol className="steps">{getFollowSteps(l).map(step=><li key={step}>{step}</li>)}</ol><h2>GitHub product behaviour</h2><p>{l.githubDetail}</p><h2>Original teaching example</h2><p>{l.practicalExample}</p><LessonDeepeningSections l={l}/><PracticalLabTask lab={relatedLab} task={l.practicalLabTask}/>{l.caseStudy&&<CaseStudy study={l.caseStudy}/>}<ScenarioCard scenario={sc}/><h2>Common exam trap</h2><p>{l.examTrap}</p><section className="must-know"><h2>What you must know after reading this</h2><ul>{l.takeaways.map(t=><li key={t}>{t}</li>)}<li>Which GitHub artifact proves the work happened: issue, pull request, check, log, artifact, approval, or instruction file.</li><li>Which action needs human review before the agent continues.</li><li>Why the wrong answers are unsafe, too vague, too broad, or not supported by evidence.</li></ul></section>{embeddedQ.length>0&&<section className="embedded-practice"><h2>Check yourself before moving on</h2><p className="muted">Answer these now. They use the same skill, but in exam-style wording.</p>{embeddedQ.map((q,index)=><QuizQuestion key={q.id} q={q} number={index+1} total={embeddedQ.length} answer={inlineAnswers[q.id]} onAnswer={a=>setInlineAnswers({...inlineAnswers,[q.id]:a})}/>)}</section>}<h2>Practice next</h2><ul className="practice-list">{relatedQ.map((q,index)=><li key={q.id}><a href={'#quiz/'+q.id}><span>Quiz question {index+1}</span>{q.question}</a></li>)}{relatedLab&&<li><a href={'#labs/'+relatedLab.id}><span>Lab</span>{relatedLab.title}</a></li>}{lessonMocks.map(m=><li key={m.id}><a href={'#mock/'+m.id}><span>Mock exam</span>{m.title}</a></li>)}</ul><h2>Revision questions</h2><ol>{l.revisionQuestions.map(r=><li key={r}>{r}</li>)}</ol></article><div className="lesson-rail"><LessonTracker lesson={l} practice={practice}/><SourcePanel ids={l.sourceIds}/></div></div></section>}
function CaseStudy({study}){return <section className="case-study"><h2>{study.title}</h2><dl><div><dt>Repository</dt><dd>{study.repository}</dd></div><div><dt>Issue</dt><dd>{study.issue}</dd></div><div><dt>Situation</dt><dd>{study.situation}</dd></div><div><dt>Decision</dt><dd>{study.decision}</dd></div><div><dt>Wrong move</dt><dd>{study.wrongMove}</dd></div><div><dt>Review artifact</dt><dd>{study.reviewArtifact}</dd></div><div><dt>Reviewer question</dt><dd>{study.reviewerQuestion}</dd></div></dl></section>}
function ScenarioCard({scenario}){return <aside className="scenario-card"><h3>{scenario.title}</h3><p>{scenario.body||scenario.prompt}</p>{scenario.goodAnswer&&<p><strong>Strong answer:</strong> {scenario.goodAnswer}</p>}</aside>}

function Walkthroughs({id}){const selected=id&&byId(uiWalkthroughs,id); if(id&&!selected) return <NotFound type="Walkthrough" id={id} backHref="#walkthroughs"/>; const list=selected?[selected]:uiWalkthroughs; return <section><PageTitle eyebrow="GitHub control-plane practice" title="UI workflow walkthroughs" text="Original schematic walkthroughs for the GitHub flows GH-600 expects you to understand. These are not copied screenshots; they are accessible study diagrams and verification checklists."/><div className={selected?'content-stack':'cards library-list'}>{list.map(w=><WalkthroughCard key={w.id} item={w}/>)}</div></section>}
function WalkthroughCard({item}){return <article className="card walkthrough"><span className="badge">{item.domainIds.join(', ')}</span><h2>{item.title}</h2><div className="mock-screen" role="img" aria-label={'Schematic GitHub screen for '+item.title}><div className="mock-top"><span></span><span></span><span></span><strong>{item.screen.area}</strong></div><div className="mock-body"><h3>{item.screen.primary}</h3><p>{item.screen.secondary}</p><div className="mock-badges">{item.screen.badges.map(b=><span key={b}>{b}</span>)}</div></div></div><h3>Steps</h3><ol>{item.steps.map(s=><li key={s}>{s}</li>)}</ol><h3>What to verify</h3><ul>{item.verify.map(v=><li key={v}>{v}</li>)}</ul><p><strong>Exam trap:</strong> {item.examTrap}</p><SourceLinks ids={item.sourceIds}/></article>}

function Labs({id}){const selected=id&&byId(labs,id); if(id&&!selected) return <NotFound type="Lab" id={id} backHref="#labs"/>; const list=selected?[selected]:labs; const capstones=labs.filter(l=>l.labType==='Capstone project').length; return <section><PageTitle eyebrow="Hands-on" title="Practical labs" text="Labs turn GH-600 knowledge into GitHub artifacts, validation evidence, and recovery habits."/><section className="guide-card"><h2>Lab path</h2><p>Start with focused labs for one skill, then use capstones to rehearse a full issue-to-PR agentic SDLC workflow.</p><div className="cards small-cards"><div className="mini"><span>Total labs</span><strong>{labs.length}</strong></div><div className="mini"><span>Capstones</span><strong>{capstones}</strong></div><div className="mini"><span>Advanced practice</span><strong>{labs.filter(l=>l.labType==='Advanced practice').length}</strong></div></div></section><div className={selected?'content-stack':'cards library-list'}>{list.map(l=><LabCard key={l.id} lab={l}/>)}</div></section>}
function LabCard({lab}){return <article className="card lab-card"><span className="badge">{lab.labType||lab.domain}</span><h2>{lab.title}</h2><p className="muted">{lab.domain}</p><p className="lab-objective"><strong>Objective:</strong> {lab.objective}</p><div className="lab-section"><h3>Required tools</h3><ul>{lab.requiredTools.map(x=><li key={x}>{x}</li>)}</ul></div><div className="lab-section"><h3>Steps</h3><ol>{lab.steps.map(x=><li key={x}>{x}</li>)}</ol></div><dl className="lab-notes"><div><dt>Expected result</dt><dd>{lab.expectedResult}</dd></div><div><dt>Validation</dt><dd>{lab.validation}</dd></div><div><dt>Common failure</dt><dd>{lab.commonFailure}</dd></div><div><dt>Recovery</dt><dd>{lab.recovery}</dd></div><div><dt>Exam relevance</dt><dd>{lab.examRelevance}</dd></div></dl><SourceLinks ids={lab.sourceIds}/></article>}
function SourceLinks({ids}){return <p className="sources-inline">Sources: {sourceNames(ids).map(s=><a key={s.id} href={s.url} target="_blank" rel="noreferrer">{s.title}</a>)}</p>}
function getQuizStats(progress){return progress.quizPractice||{domains:{},skills:{}}}
function domainPracticeSummary(progress){const stats=getQuizStats(progress).domains||{}; return blueprint.domains.map(d=>{const s=stats[d.id]||{attempted:0,correct:0}; return {...d,attempted:s.attempted||0,correct:s.correct||0,percent:s.attempted?pct(s.correct,s.attempted):0};});}
function adaptiveQuizPool(domain,progress){const base=quizzes.filter(q=>domain==='all'||q.domainId===domain); const summary=domainPracticeSummary(progress); const weakIds=summary.filter(d=>d.attempted>0&&d.percent<75).map(d=>d.id); if(domain!=='all'||weakIds.length===0) return base.slice(0,30); const weak=base.filter(q=>weakIds.includes(q.domainId)).slice(0,22); const fill=base.filter(q=>!weakIds.includes(q.domainId)).slice(0,8); return [...weak,...fill].slice(0,30);}

function Quiz({id,progress,setProgress}){const [domain,setDomain]=useState('all'); const [mode,setMode]=useState('standard'); const [answers,setAnswers]=useState({}); const selected=id&&byId(quizzes,id); if(id&&!selected) return <NotFound type="Quiz question" id={id} backHref="#quiz"/>; const pool=(id?[selected]:mode==='adaptive'?adaptiveQuizPool(domain,progress):quizzes.filter(q=>domain==='all'||q.domainId===domain).slice(0,30)); const answeredCount=Object.keys(answers).length; const score=Object.entries(answers).filter(([qid,a])=>pool.find(q=>q.id===qid)?.correctIndex===a).length; const stats=domainPracticeSummary(progress); const weak=stats.filter(d=>d.attempted>0&&d.percent<75); const recordAnswer=(q,a)=>{setAnswers({...answers,[q.id]:a}); const correct=a===q.correctIndex; const current=getQuizStats(progress); const domainStats=current.domains||{}; const skillStats=current.skills||{}; const ds=domainStats[q.domainId]||{attempted:0,correct:0}; const ss=skillStats[q.skillId]||{attempted:0,correct:0}; setProgress({...progress,quizPractice:{domains:{...domainStats,[q.domainId]:{attempted:ds.attempted+1,correct:ds.correct+(correct?1:0),lastAnswered:new Date().toISOString()}},skills:{...skillStats,[q.skillId]:{attempted:ss.attempted+1,correct:ss.correct+(correct?1:0),lastAnswered:new Date().toISOString()}}}});}; return <section><PageTitle eyebrow="Practice" title="Quiz engine" text="Immediate feedback, wrong-answer rationale, domain tags, skill tags, and adaptive weak-area review."/><section className="guide-card quiz-guide" aria-labelledby="quiz-how-to"><h2 id="quiz-how-to">How to use this quiz</h2><ol className="steps"><li>Read the question number first so you always know where you are.</li><li>Choose one answer. Feedback appears directly below the question.</li><li>Read why the wrong answers are wrong before moving to the next question.</li><li>Use adaptive mode after a few attempts so weaker domains get more repetitions.</li></ol></section><div className="toolbar"><label className="filter-control">Filter by domain <select value={domain} onChange={e=>{setDomain(e.target.value); setAnswers({});}}><option value="all">All domains</option>{blueprint.domains.map(d=><option key={d.id} value={d.id}>{d.title}</option>)}</select></label><label className="filter-control">Practice mode <select value={mode} onChange={e=>{setMode(e.target.value); setAnswers({});}}><option value="standard">Standard</option><option value="adaptive">Adaptive weak areas</option></select></label></div>{weak.length>0&&<div className="panel"><h2>Adaptive focus</h2><p>More reps will be pulled from: {weak.map(d=>d.title).join(', ')}.</p></div>}<div aria-live="polite" className="score">Answered {answeredCount} of {pool.length}. Score: {score}/{answeredCount || pool.length}</div><div className="cards small-cards">{stats.map(d=><div className="mini" key={d.id}><span>{d.title}</span><strong>{d.attempted?d.percent+'%': 'new'}</strong><small>{d.attempted} attempts</small></div>)}</div>{pool.map((q,index)=><QuizQuestion key={q.id} q={q} number={index+1} total={pool.length} answer={answers[q.id]} onAnswer={a=>recordAnswer(q,a)}/>)}</section>}

function QuizQuestion({q,answer,onAnswer,number,total,showFeedback=answer!==undefined,lockAfterAnswer=true}) {
 const headingId='question-heading-'+q.id;
 const metaId='question-meta-'+q.id;
 const answered=answer!==undefined;
 const optionClass=(i)=>{
  if(showFeedback) return 'option '+(i===q.correctIndex?'correct':answered&&i===answer?'wrong':'');
  return 'option '+(answer===i?'selected':'');
 };
 const feedbackIntro=answered?(answer===q.correctIndex?'Correct.':'Not quite.'):'Unanswered.';
 return <article className="question" aria-labelledby={headingId} aria-describedby={metaId}><p className="question-counter">Question {number} of {total}</p><p id={metaId} className="eyebrow">{q.domain} · {q.difficulty}</p><h2 id={headingId}>{q.question}</h2><div className="options-list" role="group" aria-label={'Answer choices for question '+number}>{q.options.map((o,i)=><button key={o} className={optionClass(i)} onClick={()=>onAnswer(i)} disabled={lockAfterAnswer&&(answered||showFeedback)} aria-describedby={showFeedback?metaId:undefined}><span className="option-prefix">{String.fromCharCode(65+i)}.</span> {o}</button>)}</div>{showFeedback&&<div className="feedback" role="status"><p>{feedbackIntro} {q.correctExplanation}</p>{q.wrongRationales.map(w=><p key={w.optionIndex}><strong>Option {String.fromCharCode(65+w.optionIndex)}:</strong> {w.rationale}</p>)}<SourceLinks ids={q.sourceIds}/></div>}</article>
}
function MockExam({id,progress,setProgress}) {
 const forms=[...new Set(examSimulatorQuestions.map(q=>q.form))].sort().map((form,index)=>({id:form,title:'GH-600 Scenario Exam '+String.fromCharCode(65+index),durationMinutes:120}));
 const initial=forms.find(f=>f.id===id)?.id||forms[0].id;
 const [examId,setExamId]=useState(initial);
 const [review,setReview]=useState(false);
 const [submitted,setSubmitted]=useState(false);
 const [answers,setAnswers]=useState({});
 const exam=forms.find(f=>f.id===examId)||forms[0];
 const qs=examSimulatorQuestions.filter(q=>q.form===examId);
 const answeredCount=qs.filter(q=>answers[q.id]!==undefined).length;
 const unansweredCount=qs.length-answeredCount;
 const score=qs.filter(q=>answers[q.id]===q.correctIndex).length;
 const percent=pct(score,qs.length);
 const byDomain=blueprint.domains.map(d=>{const dqs=qs.filter(q=>q.domainId===d.id); return {domain:d.title,score:dqs.filter(q=>answers[q.id]===q.correctIndex).length,total:dqs.length,percent:pct(dqs.filter(q=>answers[q.id]===q.correctIndex).length,dqs.length)};});
 const weak=byDomain.filter(d=>submitted&&d.total&&d.percent<70).map(d=>d.domain);
 const ready=submitted&&percent>=80&&weak.length===0;
 const changeExam=(next)=>{setExamId(next);setAnswers({});setSubmitted(false);setReview(false);};
 const recordAnswer=(questionId,answerIndex)=>{if(submitted||review) return; setAnswers({...answers,[questionId]:answerIndex});};
 const saveScore=()=>{setSubmitted(true);setReview(true);setProgress({...progress,mockScores:{...progress.mockScores,[examId]:percent},mockDomainScores:{...(progress.mockDomainScores||{}),[examId]:byDomain}})};
 return <section><PageTitle eyebrow="Exam simulator" title="GH-600 scenario exam simulator" text={forms.length+' timed 60-question scenario exams aligned to the official GH-600 domain weights. Use this after studying modules, labs, and quizzes.'}/><section className="guide-card exam-guide"><h2>How to use exam mode</h2><ol className="steps"><li>Choose a form and set aside up to 120 minutes.</li><li>Answer all questions before opening review mode.</li><li>Submit once, then inspect domain scores and rationales.</li><li>Retake only after reviewing weak modules and doing related labs.</li></ol></section><div className="toolbar"><label className="filter-control">Exam <select value={examId} onChange={e=>changeExam(e.target.value)}>{forms.map(m=><option key={m.id} value={m.id}>{m.title}</option>)}</select></label><button className="button" onClick={()=>setReview(!review)}>{review?'Hide rationales':'Review answer key'}</button><button className="button" onClick={()=>{setAnswers({});setSubmitted(false);setReview(false);}}>Reset form</button><button className="button primary" onClick={saveScore}>Submit and save score</button></div><div className="score" aria-live="polite">{exam.title}: answered {answeredCount} of {qs.length}. {unansweredCount>0?unansweredCount+' unanswered. ':''}{submitted?'Score: '+score+'/'+qs.length+' ('+percent+'%).':'Score hidden until submit.'} {exam.durationMinutes} minutes recommended.</div>{submitted&&<div className="panel"><h2>{ready?'Readiness signal: strong':'Readiness signal: keep studying'}</h2><p>{ready?'You reached 80% or higher with no domain below 70%. Keep reviewing rationales and run another form before booking.':'Review the low domains, revisit the related modules, and complete at least one lab before retrying.'}</p>{weak.length>0&&<p><strong>Weak domains:</strong> {weak.join(', ')}</p>}</div>}<div className="cards small-cards">{byDomain.map(d=><div className="mini" key={d.domain}>{d.domain}<strong>{submitted?d.percent+'%':d.total+' q'}</strong></div>)}</div>{qs.map((q,index)=><QuizQuestion key={q.id} q={q} number={index+1} total={qs.length} answer={answers[q.id]} onAnswer={a=>recordAnswer(q.id,a)} showFeedback={submitted||review} lockAfterAnswer={submitted||review}/>)}</section>
}

function Flashcards({progress,setProgress}){const [q,setQ]=useState(''); const [filter,setFilter]=useState('all'); const [flipped,setFlipped]=useState({}); const now=Date.now(); const status=(card)=>{const raw=progress.flashcards?.[card.id]; return typeof raw==='object'?raw:{state:raw||'new'};}; const due=(card)=>{const s=status(card); return !s.nextReview||Date.parse(s.nextReview)<=now||s.state==='review';}; const mark=(card,state)=>{const current=status(card); const count=(current.reviewCount||0)+1; const days=state==='known'?(count>=3?14:4):1; const next=new Date(Date.now()+days*86400000).toISOString(); setProgress({...progress,flashcards:{...progress.flashcards,[card.id]:{state,reviewCount:count,lastReviewed:new Date().toISOString(),nextReview:next}}});}; const cards=flashcards.filter(c=>(c.front+c.back).toLowerCase().includes(q.toLowerCase())).filter(c=>filter==='all'||(filter==='due'?due(c):status(c).state===filter)).slice(0,90); const dueCount=flashcards.filter(due).length; return <section><PageTitle eyebrow="Recall" title="Flashcards" text="Search, flip, and mark cards as known or needs review. Spaced repetition progress is saved locally."/><div className="toolbar"><label className="search"><Search aria-hidden="true"/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search flashcards"/></label><label className="filter-control">Filter <select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All cards</option><option value="due">Due now</option><option value="review">Needs review</option><option value="known">Known</option></select></label></div><div className="score">{dueCount} cards due now. Marking a card known schedules it later; needs review brings it back sooner.</div><div className="flash-grid recall-list">{cards.map((c,index)=>{const s=status(c); return <article className="flash" key={c.id}><button onClick={()=>setFlipped({...flipped,[c.id]:!flipped[c.id]})}><span>Card {index+1} · {c.domainId} · {s.state||'new'}</span><strong>{flipped[c.id]?c.back:c.front}</strong>{s.nextReview&&<small>Next review: {new Date(s.nextReview).toLocaleDateString()}</small>}</button><div className="actions"><button onClick={()=>mark(c,'known')}>Known</button><button onClick={()=>mark(c,'review')}>Needs review</button></div></article>})}</div></section>}

function Glossary({id}){const [q,setQ]=useState(''); const selected=id&&byId(glossary,id); if(id&&!selected) return <NotFound type="Glossary term" id={id} backHref="#glossary"/>; if(selected) return <section><Breadcrumbs items={[{label:'Glossary',href:routeHref('glossary')}]} current={selected.term}/><PageTitle eyebrow="Glossary term" title={selected.term} text={selected.definition}/><div className="panel"><h2>Related lessons</h2>{selected.relatedLessons.map(lessonId=><p key={lessonId}><a href={routeHref('lesson',lessonId)}>{byId(lessons,lessonId)?.title||lessonId}</a></p>)}<h2>Source mapping</h2><SourceLinks ids={selected.sourceIds}/></div></section>; const terms=glossary.filter(g=>(g.term+g.definition).toLowerCase().includes(q.toLowerCase())); return <section><PageTitle eyebrow="Reference" title="Glossary" text="Search GitHub, AI-agent, governance, MCP, and SDLC terms."/><label className="search"><Search aria-hidden="true"/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search glossary"/></label><div className="cards glossary-list">{terms.map(g=><article className="card" key={g.id}><h2><a href={routeHref('glossary',g.id)}>{g.term}</a></h2><p>{g.definition}</p>{g.relatedLessons.map(id=><a key={id} href={routeHref('lesson',id)}>{byId(lessons,id)?.title}</a>)}</article>)}</div></section>}
function TemplateArraySection({title,items}){return items?.length?<><h2>{title}</h2><ul>{items.map(item=><li key={item}>{item}</li>)}</ul></>:null}
function TemplateDetailFields({template}){return <><h2>Owner</h2><p>{template.owner}</p><TemplateArraySection title="Required fields" items={template.requiredFields}/><TemplateArraySection title="Evidence" items={template.evidence}/><TemplateArraySection title="Approval and review" items={template.approvalReview}/><TemplateArraySection title="Failure modes" items={template.failureModes}/><TemplateArraySection title="Recovery or rollback" items={template.recoveryRollback}/><TemplateArraySection title="Security and compliance" items={template.securityCompliance}/>{template.gh600Relevance&&<><h2>GH-600 relevance</h2><p>{template.gh600Relevance}</p></>}{template.miniExample&&<><h2>Mini-example</h2><p><strong>Scenario:</strong> {template.miniExample.scenario}</p><p><strong>Completed example:</strong> {template.miniExample.completedExample}</p></>}<h2>Sources</h2><SourceLinks ids={template.sourceIds||[]}/></>}
function DocumentationLibrary({id}){const repo='https://github.com/CarlasHub/gh600-agentic-ai-study-site'; const selected=id&&templateLibrary.templates.find(t=>t.id===id); if(id&&!selected) return <NotFound type="Template" id={id} backHref="#library"/>; if(selected){const section=templateLibrary.sections.find(s=>s.id===selected.sectionId); return <section><Breadcrumbs items={[{label:'Template library',href:'#library'}]} current={selected.title}/><PageTitle eyebrow={section?.title||'Template'} title={selected.title} text={selected.goal}/><div className="grid two library-detail"><div className="panel"><h2>Suggested use</h2><p>{selected.suggestedUse}</p><h2>File path</h2><p><code>{selected.filePath}</code></p><div className="actions"><a className="button primary" href={repo+'/blob/main/'+selected.filePath} target="_blank" rel="noreferrer">Open template file</a><a className="button" href="#library">Back to library</a></div></div><div className="panel"><h2>Placeholders</h2><div className="template-tags">{selected.placeholders.map(item=><code key={item}>{'{{'+item+'}}'}</code>)}</div><h2>Expectations</h2><ul>{selected.expectations.map(item=><li key={item}>{item}</li>)}</ul><TemplateDetailFields template={selected}/></div></div></section>} return <section><PageTitle eyebrow="Template library" title={templateLibrary.title} text={templateLibrary.summary}/><section className="guide-card"><h2>How to use the library</h2><p>Start with the task intake templates, add repository instructions, require a plan before edits, and use evaluation templates to turn trace evidence and failures into future checks.</p><div className="actions"><a className="button primary" href={repo+'/blob/main/docs/TEMPLATE_LIBRARY.md'} target="_blank" rel="noreferrer">Open docs index</a><a className="button" href="#lesson/domain-1-lesson-01-identify-steps-for-agents-to-perform">See in a lesson</a></div></section>{templateLibrary.sections.map(section=>{const items=templateLibrary.templates.filter(t=>t.sectionId===section.id); return <section className="library-section" key={section.id}><div className="library-section-heading"><p className="eyebrow">{items.length} templates</p><h2>{section.title}</h2><p className="muted">{section.description}</p></div><div className="cards library-template-grid">{items.map(t=><article className="card template-card" key={t.id}><span className="badge">{t.filePath}</span><h3><a href={'#library/'+t.id}>{t.title}</a></h3><p>{t.goal}</p><p className="muted"><strong>Use when:</strong> {t.suggestedUse}</p><div className="template-tags">{t.placeholders.slice(0,5).map(item=><code key={item}>{'{{'+item+'}}'}</code>)}</div><a className="button small" href={'#library/'+t.id}>Open template</a></article>)}</div></section>})}</section>}
function AccuracyDashboard(){const repo='https://github.com/CarlasHub/gh600-agentic-ai-study-site'; const reportLinks=[['Data accuracy report',accuracyFramework.reports.dataAccuracy],['Source currentness report',accuracyFramework.reports.sourceCurrentness],['Action log',accuracyFramework.reports.actionLog],['Framework docs','docs/DATA_ACCURACY_FRAMEWORK.md']]; const sourceRows=sourceStatus.sources||[]; const queue=accuracyStatus.reviewQueue||{high:0,medium:0,total:0}; return <section><PageTitle eyebrow="Accuracy" title="Source monitoring and content validation" text="This page shows the current validation framework, source snapshot, automated report status, and the path for reporting suspected content drift."/><div className="stats"><div className="stat"><CheckCircle2 aria-hidden="true"/><strong>{accuracyStatus.status}</strong><span>Data accuracy status</span></div><div className="stat"><FileText aria-hidden="true"/><strong>{accuracyStatus.contentItemsChecked||lessons.length+quizzes.length+examSimulatorQuestions.length+labs.length+flashcards.length}</strong><span>Content records checked</span></div><div className="stat"><Globe2 aria-hidden="true"/><strong>{sourceRows.length||sources.length}</strong><span>Tracked official sources</span></div><div className="stat"><ShieldCheck aria-hidden="true"/><strong>{queue.total}</strong><span>Manual review flags</span></div></div><section className="grid two"><div className="panel"><h2>Validation baseline</h2><dl className="lab-notes"><div><dt>Framework version</dt><dd>{accuracyFramework.frameworkVersion}</dd></div><div><dt>Source snapshot</dt><dd>{accuracyStatus.sourceSnapshot||accuracyFramework.sourceSnapshot.id}</dd></div><div><dt>Accuracy scan</dt><dd>{accuracyStatus.checkedAt?new Date(accuracyStatus.checkedAt).toLocaleString():'Not generated yet'}</dd></div><div><dt>Source check</dt><dd>{sourceStatus.lastChecked||accuracyStatus.sourceLastChecked||'Not generated yet'}</dd></div></dl></div><div className="panel"><h2>Reports and reporting</h2><p className="muted">Maintainers should review source changes before release recommendations and record decisions in the action log.</p><div className="actions">{reportLinks.map(([label,path])=><a key={path} className="button" href={repo+'/blob/main/'+path} target="_blank" rel="noreferrer">{label}</a>)}<a className="button primary" href={accuracyStatus.userReportUrl||accuracyFramework.userReporting.issueUrl} target="_blank" rel="noreferrer">Report content drift</a></div></div></section><div className="table-wrap"><h2>Source review states</h2><table><thead><tr><th>Source</th><th>Status</th><th>Review state</th><th>Last modified</th><th>Signals</th></tr></thead><tbody>{sourceRows.map(s=><tr key={s.id}><td><a href={s.url} target="_blank" rel="noreferrer">{s.title}</a></td><td>{s.status}</td><td>{s.reviewState||'legacy baseline'}</td><td>{s.lastModified||''}</td><td>{(s.changedSignals||[]).join(', ')||s.note||'OK'}</td></tr>)}</tbody></table></div></section>}
function Readiness({progress}){const studied=pct(Object.values(progress.lessons||{}).filter(Boolean).length,lessons.length); const mockBest=Math.max(0,...Object.values(progress.mockScores||{})); const labReady=studied>80; const ready=studied>=90&&mockBest>=80; return <section><PageTitle eyebrow="Readiness" title={ready?'Ready evidence looks strong':'Not ready yet'} text="Readiness is based on studied skills, mock score, quiz practice, and completed labs. This page does not pretend readiness without evidence."/><div className="grid two"><div className="panel"><h2>Evidence</h2><ProgressBar label="Lessons studied" value={studied}/><ProgressBar label="Best mock exam" value={mockBest}/><ProgressBar label="Coverage matrix" value={100}/></div><div className="panel"><h2>Checklist</h2>{readinessData.criteria.map(c=><label className="check" key={c}><input type="checkbox" readOnly checked={c.includes('coverage')|| (c.includes('mock')&&mockBest>=80) || (c.includes('lab')&&labReady) || (c.includes('studied')&&studied>=90)}/>{c}</label>)}</div></div><div className="panel"><h2>Final revision plan</h2><ol><li>Complete unstuck lessons in the lowest-progress domain.</li><li>Retake quizzes for questions answered incorrectly.</li><li>Complete one lab from each domain.</li><li>Score 80%+ on at least one mock exam with no domain below 70%.</li><li>Read the cram guide the day before the exam.</li><li>Open the Accuracy page and confirm source currentness before booking.</li><li>Use the walkthroughs page to rehearse issue assignment, PR review, Actions evidence, branch protection, rulesets, CODEOWNERS, environments, MCP, and session logs.</li></ol></div></section>}
function StudyPlan(){return <section><PageTitle eyebrow="Plan" title="Study schedules" text="Choose the pace that matches your deadline."/>{Object.entries(studyPlans).map(([name,items])=><div className="panel" key={name}><h2>{name.replace(/([A-Z])/g,' $1')}</h2><ol>{items.map(i=><li key={i}>{i}</li>)}</ol></div>)}</section>}
function ReferenceAid({title,items}){return <div className="reference-aid"><h3>{title}</h3><ol>{items.map(item=><li key={item}>{item}</li>)}</ol></div>}
function CramGuide(){const aids=[['Agent architecture flow',['Issue defines goal and boundary','Agent produces plan','Tools execute inside scope','Checks and artifacts create evidence','Human reviews and approves risk']],['MCP flow',['Client discovers server tools','Allow list restricts available tools','Agent requests a tool call','Tool result returns as grounded context','Audit trail records capability use']],['Memory hierarchy',['Immediate task context','Durable GitHub artifacts','External memory store','Shared multi-agent state','Pruned or expired stale context']],['Multi-agent pattern',['Planner defines work','Builder changes branch','Tester validates evidence','Reviewer classifies risk','Human owns final approval']]]; return <section><PageTitle eyebrow="Final review" title="Cram guide" text="Use this after you have studied the modules. If you are just starting, go to Modules or Study plan first."/><section className="guide-card start-guide"><h2>Do not start here</h2><p>The cram guide is a final review page. Start with the modules, then use lessons, labs, quizzes, flashcards, mock exams, and finally this page.</p><div className="actions"><a className="button primary" href="#domains">Start with modules</a><a className="button" href="#study-plan">Pick a study plan</a><a className="button" href="#lesson/domain-1-lesson-01-identify-steps-for-agents-to-perform">Open first lesson</a></div></section><div className="panel"><h2>High-yield topics</h2><ul>{cramGuide.highYield.map(x=><li key={x}>{x}</li>)}</ul></div><section className="panel"><h2>Visual reference aids</h2><div className="cards small-cards">{aids.map(([title,items])=><ReferenceAid key={title} title={title} items={items}/>)}</div></section>{cramGuide.decisionTables.map(t=><div className="table-wrap" key={t.title}><h2>{t.title}</h2><table><tbody>{t.rows.map((r,i)=><tr key={i}>{r.map(c=><td key={c}>{c}</td>)}</tr>)}</tbody></table></div>)}<div className="panel"><h2>Cheat sheets</h2>{cramGuide.cheatsheets.map(x=><p key={x}>{x}</p>)}</div><div className="panel"><h2>Currentness check</h2><p>Before exam day, compare the official Microsoft GH-600 study guide with the coverage matrix. Update any changed skill, source, quiz, lab, or flashcard before trusting the readiness result.</p><p><a href="https://learn.microsoft.com/en-gb/credentials/certifications/resources/study-guides/gh-600" target="_blank" rel="noreferrer">Open official GH-600 study guide</a></p></div></section>}

function PageTitle({eyebrow,title,text}){return <div className="page-title"><p className="eyebrow">{eyebrow}</p><h1>{title}</h1>{text&&<p>{text}</p>}</div>}
function App(){const route=useHashRoute(); const [progress,setProgress]=useProgress(); useEffect(()=>{applyRouteSeo(route); document.getElementById('seo-prerender')?.remove(); requestAnimationFrame(()=>{const active=document.querySelector('nav a[aria-current="page"]'); const nav=active?.closest('nav'); if(active&&nav) nav.scrollLeft=active.offsetLeft-(nav.clientWidth-active.clientWidth)/2;});},[route]); let page; if(route.page==='blueprint') page=<Blueprint/>; else if(route.page==='domains') page=<Domains progress={progress}/>; else if(route.page==='domain') page=<DomainPage id={route.id} progress={progress} setProgress={setProgress}/>; else if(route.page==='lessons') page=<Lessons progress={progress} setProgress={setProgress}/>; else if(route.page==='lesson') page=<Lesson id={route.id} progress={progress} setProgress={setProgress}/>; else if(route.page==='walkthroughs') page=<Walkthroughs id={route.id}/>; else if(route.page==='library') page=<DocumentationLibrary id={route.id}/>; else if(route.page==='labs') page=<Labs id={route.id}/>; else if(route.page==='quiz') page=<Quiz id={route.id} progress={progress} setProgress={setProgress}/>; else if(route.page==='mock') page=<MockExam id={route.id} progress={progress} setProgress={setProgress}/>; else if(route.page==='flashcards') page=<Flashcards progress={progress} setProgress={setProgress}/>; else if(route.page==='glossary') page=<Glossary id={route.id}/>; else if(route.page==='readiness') page=<Readiness progress={progress}/>; else if(route.page==='accuracy') page=<AccuracyDashboard/>; else if(route.page==='study-plan') page=<StudyPlan/>; else if(route.page==='cram') page=<CramGuide/>; else page=<Home progress={progress}/>; return <Layout progress={progress} route={route}>{page}</Layout>}

const rootElement=document.getElementById('root');
const appRoot=globalThis.__gh600Root||createRoot(rootElement);
globalThis.__gh600Root=appRoot;
appRoot.render(<App />);
